/**
 * Build the committed country range table from a DB-IP country CSV (phase 06,
 * ACTIVITY-06, plan 06-04, RESEARCH Pattern 9, T-06-17, T-06-18).
 *
 * ## Why a script and not a runtime lookup
 *
 * The app never geolocates anything. It reads a table this script generated at
 * build time and committed, which is the project constraint "geo assets are
 * build-time only" and the reason no runtime dependency on a geo database
 * exists at all. The table is regenerated by re-running this file, so it is a
 * derived artifact with a printed source hash rather than an opaque binary.
 *
 * ## Why it runs as a plain Node `.ts` file
 *
 * `node scripts/geo/build-country-table.ts` uses native type stripping, so
 * there is no build step for the build step, no ts-node, and no flag for CI to
 * remember. That only works while the file stays ERASABLE — no `enum`, no
 * `namespace`, no constructor parameter property, no decorators — because
 * stripping replaces types rather than compiling them. `erasableSyntaxOnly` in
 * `tsconfig.node.json` is what keeps that honest, and it is why the shared
 * writer is a module of plain functions next to this one.
 *
 * ## Why the input is STREAMED (T-06-18)
 *
 * The country CSV is 31 MB raw and the city CSV plan 06-09 builds from is
 * 693 MB. `createReadStream` -> `createGunzip` -> `readline` means the peak
 * cost of a build is the table, not the text; reading a 693 MB file with
 * `readFile` would put a string this project has no reason to hold in memory.
 * The gzip is detected from the first two BYTES rather than from the
 * extension, because DB-IP ships `.csv.gz` and plan 06-09's hermetic e2e
 * fixture ships the same bytes under a different name, and a wrong answer from
 * a name would be a decompression error a long way from its cause.
 *
 * ## Where the CSV comes from
 *
 * `--download` fetches the OFFICIAL DB-IP monthly file (phase 06, plan 06-04
 * Task 2, RESEARCH Decision 1) and `--csv` reads one from disk. The decision is
 * the official downloads rather than the `@ip-location-db` npm mirror, and it is
 * pinned in `tests/unit/geo/source-decision.test.ts`; the short version is that
 * the mirror is deprecated, stale, disputed on 2.65% of /24 blocks, and has no
 * city counterpart past 2025-01. Keeping `--csv` costs nothing and is what
 * leaves the mirror usable as an offline fallback.
 *
 * ## What it prints
 *
 * Exactly one line, and everything needed to decide whether a regenerated table
 * is the table that is committed: the kind, the month the header will carry, the
 * source (a URL or a path), the range count per family, how many lines were
 * skipped and why, the byte size and the sha256 of what was written (T-06-17 — a
 * derived artifact that nobody can check is not reviewable).
 */

import { createHash } from 'node:crypto';
import { open, mkdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import readline from 'node:readline';
import { createGunzip } from 'node:zlib';
import { pathToFileURL } from 'node:url';

import { KIND_COUNTRY, encodeRangeTable, type RangeInput } from '../../src/lib/geo/range-table.ts';
import { parseCountryLine } from './lib/csv-ranges.ts';
import { downloadToFile, headStatus, resolveDbipUrl } from './lib/download.ts';

const DEFAULT_OUT = 'src/lib/geo/assets/country-table.bin';

/** The first two bytes of a gzip member. */
const GZIP_MAGIC_0 = 0x1f;
const GZIP_MAGIC_1 = 0x8b;

interface Options {
  csv: string | null;
  download: boolean;
  out: string;
  fixture: boolean;
  month: string | null;
}

/** Parse the flags. Unknown flags are an error rather than a silent no-op. */
export function parseArgs(argv: readonly string[]): Options {
  const options: Options = {
    csv: null,
    download: false,
    out: DEFAULT_OUT,
    fixture: false,
    month: null,
  };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    switch (arg) {
      // pnpm 12 forwards the separator literally (`pnpm run geo:country --args`
      // reaches this script as `script -- --args`), so the GNU convention is
      // honoured here rather than left to fail as an unknown flag.
      case '--':
        break;
      case '--csv':
        options.csv = argv[++i] ?? null;
        if (options.csv === null) usage('--csv needs a path');
        break;
      case '--download':
        options.download = true;
        break;
      case '--out':
        options.out = argv[++i] ?? null;
        if (options.out === null) usage('--out needs a path');
        break;
      case '--month':
        options.month = argv[++i] ?? null;
        if (options.month === null) usage('--month needs YYYY-MM');
        break;
      case '--fixture':
        options.fixture = true;
        break;
      default:
        usage(`unknown flag: ${arg}`);
    }
  }
  // Exactly one source. A build that took both would have two answers to which
  // month's data it is, and a build that took neither has no table to write.
  if (options.csv !== null && options.download) usage('give either --csv or --download, not both');
  if (options.csv === null && !options.download) usage('give --csv <path> or --download');
  // The month is REQUIRED for a local file (nothing else knows which one it is)
  // and FORBIDDEN for a download (the resolution already knows, and a --month
  // that was quietly ignored would label the table with the wrong month).
  if (options.download && options.month !== null) {
    usage('--download records the month it resolved; drop --month');
  }
  if (!options.download && options.month === null) usage('--month YYYY-MM is required with --csv');
  if (options.download && options.fixture) {
    usage('--fixture marks a table as test data; a downloaded file is not');
  }
  return options;
}

function usage(problem: string): never {
  process.stderr.write(
    [
      'build-country-table: ' + problem,
      '',
      'Usage:',
      '  node scripts/geo/build-country-table.ts --csv <path> --month YYYY-MM [--out <path>] [--fixture]',
      '  node scripts/geo/build-country-table.ts --download [--out <path>]',
      '',
      'The CSV may be plain or gzipped; which one it is comes from its first two bytes.',
      'The month is recorded in the table header, so a --csv build must say which source month it read.',
      '--download resolves the current UTC month from download.db-ip.com and falls back one month on a 404.',
    ].join('\n') + '\n',
  );
  process.exit(2);
}

/** True when the file's first two bytes are a gzip member header. */
export async function isGzip(filePath: string): Promise<boolean> {
  const handle = await open(filePath, 'r');
  try {
    const head = Buffer.alloc(2);
    const { bytesRead } = await handle.read(head, 0, 2, 0);
    return bytesRead === 2 && head[0] === GZIP_MAGIC_0 && head[1] === GZIP_MAGIC_1;
  } finally {
    await handle.close();
  }
}

/**
 * Read every range in a CSV, streaming, and report how many lines were skipped.
 *
 * The skipped count is returned rather than thrown on: a source that gained a
 * comment line or a header is not a broken build, but a source that LOST its
 * ranges would be, and the only way to tell the two apart is the number the
 * build prints.
 */
async function readRanges(
  filePath: string,
): Promise<{ ranges: RangeInput[]; skipped: number; v4: number; v6: number }> {
  const gzipped = await isGzip(filePath);
  const handle = await open(filePath, 'r');
  const ranges: RangeInput[] = [];
  let skipped = 0;
  let v4 = 0;
  let v6 = 0;
  try {
    // The WHOLE file goes to the gunzip, magic bytes included. A gzip member
    // begins with its own 10-byte header, so skipping the first two bytes and
    // handing the rest to createGunzip asks zlib to parse a header out of
    // deflate data and fails with Z_DATA_ERROR.
    const source = handle.createReadStream();
    const input = gzipped ? source.pipe(createGunzip()) : source;
    const lines = readline.createInterface({ input, crlfDelay: Infinity });
    for await (const line of lines) {
      const row = parseCountryLine(line);
      if (row === null) {
        skipped += 1;
        continue;
      }
      ranges.push(row);
      if (row.start.family === 4) v4 += 1;
      else v6 += 1;
    }
  } finally {
    await handle.close();
  }
  return { ranges, skipped, v4, v6 };
}

/**
 * Where the CSV came from, for the one summary line.
 *
 * T-06-17 asks for the source to be printed, and a download carries a URL and
 * its own hash while a local file carries a path. They are the same field for
 * the same reason: the committed binary has to be traceable to something a
 * reviewer can fetch.
 */
interface Source {
  label: string;
  month: string;
  bytes: number;
  sha256: string;
}

async function main(argv: readonly string[]): Promise<void> {
  const options = parseArgs(argv);

  let csvPath = options.csv;
  let source: Source;
  let tempPath: string | null = null;

  if (options.download) {
    const resolved = await resolveDbipUrl('country', new Date(), headStatus);
    // The download lands in a temp file rather than in the working tree, and it
    // is deleted below whether or not the build succeeds: a 31 MB CSV left in
    // the repository is both untracked noise and a copy of a licensed dataset
    // nobody chose to commit.
    tempPath = path.join(tmpdir(), `dbip-country-lite-${resolved.month}-${process.pid}.csv.gz`);
    const result = await downloadToFile(resolved.url, tempPath);
    csvPath = tempPath;
    source = {
      label: resolved.url,
      month: resolved.month,
      bytes: result.bytes,
      sha256: result.sha256,
    };
  } else {
    source = { label: options.csv!, month: options.month!, bytes: 0, sha256: '' };
  }

  try {
    const { ranges, skipped, v4, v6 } = await readRanges(csvPath!);
    const bytes = encodeRangeTable(ranges, {
      kind: KIND_COUNTRY,
      month: source.month,
      fixture: options.fixture,
    });
    await mkdir(path.dirname(options.out), { recursive: true });
    await writeFile(options.out, bytes);
    const sha256 = createHash('sha256').update(bytes).digest('hex');
    process.stdout.write(
      [
        'kind=country',
        `month=${source.month}`,
        `source=${source.label}`,
        `source_v4=${v4}`,
        `source_v6=${v6}`,
        `skipped=${skipped}`,
        `bytes=${bytes.length}`,
        `fixture=${options.fixture}`,
        `sha256=${sha256}`,
        `out=${options.out}`,
      ].join(' ') + '\n',
    );
  } finally {
    if (tempPath !== null) await rm(tempPath, { force: true });
  }
}

// A module-local check rather than a bare call, so a test can import the flag
// parser and the gzip sniffer without running a build.
if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main(process.argv.slice(2));
}
